DROP TABLE IF EXISTS `attendance_punches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `attendance_punches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint(20) unsigned NOT NULL,
  `punched_at` datetime NOT NULL,
  `punch_status` varchar(30) NOT NULL,
  `import_row_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ap_punch` (`employee_id`,`punched_at`,`punch_status`),
  KEY `idx_ap_date` (`punched_at`,`employee_id`),
  KEY `fk_ap_row` (`import_row_id`),
  CONSTRAINT `fk_ap_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_ap_row` FOREIGN KEY (`import_row_id`) REFERENCES `attendance_import_rows` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1338 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

