--
-- Table structure for table `branches`
--

DROP TABLE IF EXISTS `branches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `branches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` bigint(20) unsigned DEFAULT NULL,
  `area_id` bigint(20) unsigned DEFAULT NULL,
  `default_business_unit_id` bigint(20) unsigned DEFAULT NULL,
  `default_legal_entity_id` bigint(20) unsigned DEFAULT NULL,
  `site_type` varchar(30) NOT NULL DEFAULT 'RETAIL_STORE',
  `source_name_text` varchar(160) DEFAULT NULL,
  `source_company_text` varchar(160) DEFAULT NULL,
  `mapping_status` varchar(30) NOT NULL DEFAULT 'LEGACY',
  `code` varchar(30) DEFAULT NULL,
  `name` varchar(160) NOT NULL,
  `address_text` varchar(255) DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `fk_branches_client` (`client_id`),
  KEY `idx_branches_area` (`area_id`),
  KEY `idx_branches_business_unit` (`default_business_unit_id`),
  KEY `idx_branches_legal_entity` (`default_legal_entity_id`),
  CONSTRAINT `fk_branches_area` FOREIGN KEY (`area_id`) REFERENCES `areas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_branches_business_unit` FOREIGN KEY (`default_business_unit_id`) REFERENCES `business_units` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_branches_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `fk_branches_legal_entity` FOREIGN KEY (`default_legal_entity_id`) REFERENCES `legal_entities` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

